window.RP_SESSION={"id":"S-a43553f24c2c","messages":[{"id":"RP-III-0177600","time":"2026-09-14T01:37:00+09:00","room":"RP III","name":"Maria Anaïs Ésther","profile":"Maria Anaïs Ésther","identity":"unresolved","type":"dialogue","body":"@카리엔","characters":[]},{"id":"RP-III-0177601","time":"2026-09-14T01:37:00+09:00","room":"RP III","name":"딘","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" .... 이, 이런...! \"","characters":["P-1ebd61bdfafd"]},{"id":"RP-III-0177602","time":"2026-09-14T01:40:00+09:00","room":"RP III","name":"장면 서술 / 고양이 무리","profile":"루체","identity":"reviewed","type":"dialogue","body":"딘 앞에 사나운 도시 고양이들이 딘의 장바구니를 노립니다","characters":[]},{"id":"RP-III-0177603","time":"2026-09-14T01:40:00+09:00","room":"RP III","name":"장면 서술 / 고양이 무리","profile":"루체","identity":"reviewed","type":"dialogue","body":"\"캬오옹!!!\"","characters":[]},{"id":"RP-III-0177604","time":"2026-09-14T01:40:00+09:00","room":"RP III","name":"딘","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 이건 안돼-!! 이 자식들!! \"","characters":["P-1ebd61bdfafd"]},{"id":"RP-III-0177605","time":"2026-09-14T01:45:00+09:00","room":"RP III","name":"장면 서술 / 고양이 무리","profile":"루체","identity":"reviewed","type":"dialogue","body":"장바구니 안엔 도데체 뭐가 있길래 그들이 노리는거죠?\n\n\"키야옹!!\"\n\n그 순간, 고양이중 가장 덩치가 큰 한마리가 딘의 얼굴로 뛰어듭니다!","characters":[]},{"id":"RP-III-0177606","time":"2026-09-14T01:46:00+09:00","room":"RP III","name":"딘","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"딘은 장바구니를 끌어안은 채 담벼락 너머의 구릉으로 뛰어내렸습니다.\n\n\" 크아앗! 크앗-! 우와앗-!! 와악-!! \"","characters":["P-1ebd61bdfafd"]},{"id":"RP-III-0177607","time":"2026-09-14T01:48:00+09:00","room":"RP III","name":"장면 서술 / 고양이 무리","profile":"루체","identity":"reviewed","type":"dialogue","body":"대장을 따라 달려든 고양이들의 날카로운 발톱에 딘의 등이 따끔따끔 합니다.\n몇마리는 딘의 등에 매달려있고 몇마리는 딘의 옆에서 같이 떨어지고 있네요.\n\n\"캬오오옹!!!\"","characters":[]},{"id":"RP-III-0177608","time":"2026-09-14T01:49:00+09:00","room":"RP III","name":"딘","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 트아아아앗-!! \"\n\n딘은 그 즉시 몸을 굴려 연못으로 뛰어들었습니다.","characters":["P-1ebd61bdfafd"]},{"id":"RP-III-0177609","time":"2026-09-14T01:52:00+09:00","room":"RP III","name":"장면 서술 / 고양이 무리","profile":"루체","identity":"reviewed","type":"dialogue","body":"첨-벙!!\n\n큰소리가 나며 연못물이 출렁입니다.\n동시에 고양이들이 물에서 벗어나려 아우성 치는군요.\n\n\"야옹!!! 느야옹~!!\"\n\n그 와중에 이미 물에서 벗어난 대장 고양이는 사나운 눈빛으로 딘을 노려봅니다.\n작게 들려오는 \"키싯\"소리가 딘이 대장 고양이에게 매우 미움샀다는걸 알려주네요.","characters":[]},{"id":"RP-III-0177610","time":"2026-09-14T01:54:00+09:00","room":"RP III","name":"딘","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"부그르르륵... 부그륵...\n\n .... 뽀글.\n\n...\n ... \n  ... 퐁!\n\n수면 위로 먼저 올라온 것은 딘이 양 손으로 받쳐올린 바구니였습니다.\n\n그리곤 바구니 아래로 딘의 얼굴이 스으윽, 수면 위로 올라왔습니다.\n\n부그르르륵 부그륵..\n\n\" 푸하...ㅅ! 죽는 줄 알았네...! \"","characters":["P-1ebd61bdfafd"]},{"id":"RP-III-0177611","time":"2026-09-14T01:54:00+09:00","room":"RP III","name":"장면 서술 / 고양이 무리","profile":"루체","identity":"reviewed","type":"dialogue","body":"진짜로 궁굼하네요 딘.\n도데체 바구니 안에 뭐가있는거죠?","characters":[]},{"id":"RP-III-0177612","time":"2026-09-14T01:55:00+09:00","room":"RP III","name":"딘","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"바구니 안에 든 것은 ...","characters":["P-1ebd61bdfafd"]},{"id":"RP-III-0177613","time":"2026-09-14T01:56:00+09:00","room":"RP III","name":"장면 서술 / 고양이 무리","profile":"루체","identity":"reviewed","type":"dialogue","body":"든 것은...?","characters":[]},{"id":"RP-III-0177614","time":"2026-09-14T01:56:00+09:00","room":"RP III","name":"딘","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"흑연 열 두필입니다...!","characters":["P-1ebd61bdfafd"]},{"id":"RP-III-0177615","time":"2026-09-14T01:57:00+09:00","room":"RP III","name":"장면 서술 / 고양이 무리","profile":"루체","identity":"reviewed","type":"dialogue","body":"샵검색: #흑연","characters":[]},{"id":"RP-III-0177616","time":"2026-09-14T01:57:00+09:00","room":"RP III","name":"장면 서술 / 고양이 무리","profile":"루체","identity":"reviewed","type":"dialogue","body":"캣닢으로 착각한걸까요?","characters":[]},{"id":"RP-III-0177617","time":"2026-09-14T01:57:00+09:00","room":"RP III","name":"장면 서술 / 고양이 무리","profile":"루체","identity":"reviewed","type":"dialogue","body":"아니면 바구니가 아니라 딘을 노린걸까요?","characters":[]},{"id":"RP-III-0177618","time":"2026-09-14T01:58:00+09:00","room":"RP III","name":"딘","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"딘을 노렸을 겁니다. 그가 도시에서 새끼고양이 한 마리를 발견했고, 어디서 온 녀석이니~ 귀여워하며 머리를 좀 만져주고 있었거든요. 그게 걸린 것 같습니다.\n\n저 빌어먹게 뚱뚱한 대장 고양이한테요!","characters":["P-1ebd61bdfafd"]},{"id":"RP-III-0177619","time":"2026-09-14T01:59:00+09:00","room":"RP III","name":"장면 서술 / 고양이 무리","profile":"루체","identity":"reviewed","type":"dialogue","body":"아하! 그렇게 된 일이였군요.","characters":[]},{"id":"RP-III-0177620","time":"2026-09-14T01:59:00+09:00","room":"RP III","name":"장면 서술 / 고양이 무리","profile":"루체","identity":"reviewed","type":"dialogue","body":"어느덧 \"키싯\"거리던 대장 고양이도 사라졌습니다.","characters":[]},{"id":"RP-III-0177621","time":"2026-09-14T02:00:00+09:00","room":"RP III","name":"장면 서술 / 고양이 무리","profile":"루체","identity":"reviewed","type":"dialogue","body":"흑연은 어디다 쓰려 했던간가요?","characters":[]},{"id":"RP-III-0177622","time":"2026-09-14T02:02:00+09:00","room":"RP III","name":"딘","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"딘은 연못에서 기어 올라오며 바구니를 열어봤습니다.\n\n물에 좀 젖긴 했지만, 아직 흑연 열 두필이 부러지지 않고 잘 있습니다.\n\n\" ㅎㅎ \"\n\n머리카락에서 뚝 뚝 떨어지는 물방울.\n\n하지만 기분좋은 미소.\n\n\" 아도 선배도 분명 좋아하실거야! \"\n\n그렇게 딘은 길드로 성큼성큼 걸음을 향했습니다.","characters":["P-1ebd61bdfafd"]},{"id":"RP-III-0177623","time":"2026-09-14T02:03:00+09:00","room":"RP III","name":"장면 서술 / 고양이 무리","profile":"루체","identity":"reviewed","type":"dialogue","body":"공부용이였군요~","characters":[]},{"id":"RP-III-0177624","time":"2026-09-14T02:03:00+09:00","room":"RP III","name":"장면 서술 / 고양이 무리","profile":"루체","identity":"reviewed","type":"dialogue","body":"사이먼이 사라진 이후에도 그가 남긴 학구열은 식지 않아 다행입니다...","characters":[]},{"id":"RP-III-0177625","time":"2026-09-14T02:06:00+09:00","room":"RP III","name":"딘","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-1ebd61bdfafd"]},{"id":"RP-III-0177626","time":"2026-09-14T02:06:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
